#include <iostream>
#include <fstream>
#include <string>
#include <map>
using namespace std;

int main() {
    ifstream plik("transakcje.txt");
    string typ;
    int kwota;
    map<string, pair<int, int>> dane;
    while (plik >> typ >> kwota) {
        dane[typ].first++;
        dane[typ].second += kwota;
    }
    cout << "Podsumowanie transakcji:" << endl;
    for (auto& p : dane) {
        cout << "   " << p.first << ": " << p.second.first << " transakcji, suma: " << p.second.second << endl;
    }
    int saldo = dane["Wplata"].second - dane["Wyplata"].second;
    cout << "Saldo: " << saldo << endl;
    return 0;
}
```

Weryfikacja:
- Wplata: 500+300+1000+250+800+600 = 3450 (6 transakcji)
- Wyplata: 200+150+400+100+350+500 = 1700 (6 transakcji)
- Saldo: 3450-1700 = 1750
